  3	public final class CircularQueue<T> {
  4	
  5	    private final Object[] elements;
  6	    private int head;
  7	    private int tail;
  8	    private int size;
  9	
 10	    public CircularQueue(int capacity) {
 11	        if (capacity <= 0) {
 12	            throw new IllegalArgumentException("Capacity must be positive.");
 13	        }
 14	
 15	        elements = new Object[capacity];
 16	        head = 0;
 17	        tail = 0;
 18	        size = 0;
 19	    }
 20	
 21	    public void enqueue(T value) {
 22	        if (isFull()) {
 23	            throw new IllegalStateException("Queue is full.");
 24	        }
 25	
 26	        elements[tail] = value;
 27	        tail = advance(tail);
 28	        size++;
 29	    }
 30	
 31	    public T dequeue() {
 32	        ensureNotEmpty();
 33	
 34	        T removedValue = elementAt(head);
 35	        elements[head] = null;
 36	        head = advance(head);
 37	        size--;
 38	        return removedValue;
 39	    }
 40	
 41	    public T peekFront() {
 42	        ensureNotEmpty();
 43	        return elementAt(head);
 44	    }
 45	
 46	    public T peekRear() {
 47	        ensureNotEmpty();
 48	        return elementAt(previousIndex(tail));
 49	    }
 50	
 51	    public T getFront() {
 52	        return peekFront();
 53	    }
 54	
 55	    public T getRear() {
 56	        return peekRear();
 57	    }
 58	
 59	    public boolean isEmpty() {
 60	        return size == 0;
 61	    }
 62	
